import type { HttpClient } from '../net/HttpClient.js';
import { parseJson } from '../net/HttpClient.js';
import { SIGNATURE_HEADER, signRequestBody } from '../net/requestSigner.js';
import type { UrlBuilder } from '../net/UrlBuilder.js';
import type {
  CoinSpendStatusResponse,
  PurchaseCreateRequest,
  PurchaseCreateResponse,
  PurchaseStatusResponse,
} from './models.js';

/** REST surface for purchases (interface allows mocking). Contract §1. */
export interface PurchaseApi {
  create(accessToken: string, req: PurchaseCreateRequest): Promise<PurchaseCreateResponse>;
  /** Returns the raw response text. */
  complete(accessToken: string, paymentId: string): Promise<string>;
  status(accessToken: string, paymentId: string): Promise<PurchaseStatusResponse>;
  /** Coin-spend status keyed on the identifiers the client already holds. */
  coinSpendStatus(
    accessToken: string,
    gameName: string,
    gameTransactionId: string,
  ): Promise<CoinSpendStatusResponse>;
}

/** Default {@link PurchaseApi} over {@link HttpClient}. Mirrors C# `PurchaseApiClient`. */
export class PurchaseApiClient implements PurchaseApi {
  constructor(
    private readonly http: HttpClient,
    private readonly urls: UrlBuilder,
    private readonly signSecret: string = '',
  ) {}

  async create(
    accessToken: string,
    req: PurchaseCreateRequest,
  ): Promise<PurchaseCreateResponse> {
    const body = toSignableJson(req);
    const headers: Record<string, string> = {};
    if (this.signSecret) {
      headers[SIGNATURE_HEADER] = await signRequestBody(this.signSecret, body);
    }

    const res = await this.http.send({
      method: 'POST',
      url: this.urls.buildPurchaseCreateUrl(),
      context: 'PurchaseApiClient.Create',
      bearer: accessToken,
      body,
      headers,
    });
    return parseJson<PurchaseCreateResponse>(res);
  }

  async complete(accessToken: string, paymentId: string): Promise<string> {
    const res = await this.http.send({
      method: 'POST',
      url: this.urls.buildPurchaseCompleteUrl(),
      context: 'PurchaseApiClient.Complete',
      bearer: accessToken,
      json: { payment_id: paymentId },
    });
    return res.text;
  }

  async status(accessToken: string, paymentId: string): Promise<PurchaseStatusResponse> {
    const res = await this.http.send({
      method: 'GET',
      url: this.urls.buildPurchaseStatusUrl(paymentId),
      context: 'PurchaseApiClient.Status',
      bearer: accessToken,
    });
    return parseJson<PurchaseStatusResponse>(res);
  }

  async coinSpendStatus(
    accessToken: string,
    gameName: string,
    gameTransactionId: string,
  ): Promise<CoinSpendStatusResponse> {
    const res = await this.http.send({
      method: 'GET',
      url: this.urls.buildCoinSpendStatusUrl(gameName, gameTransactionId),
      context: 'PurchaseApiClient.CoinSpendStatus',
      bearer: accessToken,
    });
    return parseJson<CoinSpendStatusResponse>(res);
  }
}

const ESCAPES: Readonly<Record<string, string>> = {
  '"': '\\"',
  '\\': '\\\\',
  '\b': '\\b',
  '\f': '\\f',
  '\n': '\\n',
  '\r': '\\r',
  '\t': '\\t',
};

/**
 * Body of `POST /purchase/create` in the one form the backend and the client agree on:
 * keys sorted, no whitespace, every character outside printable ASCII escaped as `\uXXXX`.
 * The backend re-serializes what it received exactly this way before it recomputes the
 * signature, so these are the bytes that have to go on the wire. Mirrors C# `ToSignableJson`.
 */
export function toSignableJson(req: PurchaseCreateRequest): string {
  return (
    '{"coin_amount":' +
    String(req.coin_amount) +
    ',"game_name":' +
    jsonString(req.game_name) +
    ',"transaction_id":' +
    jsonString(req.transaction_id) +
    ',"transaction_image_url":' +
    jsonString(req.transaction_image_url) +
    ',"transaction_name":' +
    jsonString(req.transaction_name) +
    '}'
  );
}

function jsonString(value: string | undefined | null): string {
  const source = value ?? '';
  let out = '"';

  for (let i = 0; i < source.length; i++) {
    const char = source[i]!;
    const escape = ESCAPES[char];
    if (escape !== undefined) {
      out += escape;
      continue;
    }

    const code = source.charCodeAt(i);
    out += code < 0x20 || code > 0x7e ? '\\u' + code.toString(16).padStart(4, '0') : char;
  }

  return out + '"';
}
