/**
 * Contract guards for the attribution envelope (contract §8). Mirrors C#
 * `AttributionContract`.
 *
 * The analytics endpoint is unauthenticated and accepts whatever it is given,
 * so a wrong value is only ever noticed weeks later in ClickHouse. Both guards
 * below exist because that already happened (AC-10635).
 */

export const DEFAULT_CURRENCY_CODE = 'USD';

const LOG_TAG = '[EnjoylixAttributionService]';

/** A JWT is `ey…` (base64url of `{"alg"…`) in exactly three dot-separated parts. */
function looksLikeJwt(value: string): boolean {
  return value.startsWith('ey') && value.split('.').length === 3;
}

function isIso4217(value: string): boolean {
  return /^[A-Z]{3}$/.test(value);
}

/**
 * `auth_id` is the Enjoylix user id — the `id` field of `/api/v1/users/me` —
 * never an access token. A token reaching this field would be published to an
 * unauthenticated endpoint, so it is dropped rather than sent.
 */
export function normalizeAuthId(authId: string | null | undefined): string {
  if (!authId) return '';

  if (looksLikeJwt(authId)) {
    console.error(
      `${LOG_TAG} auth_id looks like an access token, not an Enjoylix user id ` +
        `(expected the 'id' field of /api/v1/users/me). Sending the event without auth_id.`,
    );
    return '';
  }

  return authId;
}

/**
 * `currency_code` is an ISO 4217 code. Display strings (`$19.99`, a localized
 * price label) used to reach it, which makes the column unusable for grouping.
 * `amount` is already in USD and the payment method is reported in `source`,
 * so USD is the consistent fallback.
 */
export function normalizeCurrencyCode(currencyCode: string | null | undefined): string {
  const normalized = (currencyCode ?? '').trim().toUpperCase();

  if (isIso4217(normalized)) return normalized;

  console.error(
    `${LOG_TAG} currency_code '${currencyCode ?? ''}' is not an ISO 4217 code ` +
      `(expected 3 letters, e.g. 'USD'). Falling back to '${DEFAULT_CURRENCY_CODE}'.`,
  );
  return DEFAULT_CURRENCY_CODE;
}
