import type { EnjoylixConfig, LoginKind, ResolvedConfig } from './config/types.js';
import { resolveConfig } from './config/resolveConfig.js';
import { UrlBuilder } from './net/UrlBuilder.js';
import { FetchHttpClient, type HttpClient } from './net/HttpClient.js';
import { RetryingHttpClient, type RetryPolicy } from './net/RetryingHttpClient.js';
import type { ValidationErrorResponse } from './net/errors.js';
import { Signal } from './common/Signal.js';
import { SessionQueryParams } from './common/SessionQueryParams.js';
import {
  WindowBrowserEnv,
  type BrowserEnv,
} from './transport/BrowserEnv.js';
import {
  LocalStorageAuthStorage,
  type AuthStorage,
} from './storage/AuthStorage.js';
import { AuthService } from './auth/AuthService.js';
import { AuthApiClient } from './auth/AuthApiClient.js';
import { BrowserAuthLoginTransport } from './auth/AuthLoginTransport.js';
import type { AuthSession } from './auth/models.js';
import { PurchaseService } from './purchase/PurchaseService.js';
import { PurchaseApiClient } from './purchase/PurchaseApiClient.js';
import type { PaymentResult, PurchaseCreateRequest } from './purchase/models.js';
import {
  AgeVerificationService,
  AgeVerificationApiClient,
} from './ageVerification/AgeVerificationService.js';
import {
  AttributionService,
  type AttributionContext,
} from './attribution/AttributionService.js';

const LOGIN_TIMEOUT_MS = 300_000; // 5 min
const ON_START_TIMEOUT_MS = 120_000; // 2 min
const PURCHASE_TIMEOUT_MS = 1_800_000; // 30 min
const AGE_TIMEOUT_MS = 300_000; // 5 min

/** Optional dependency overrides (testing / SSR / custom transports). */
export interface EnjoylixSdkDeps {
  httpClient?: HttpClient;
  storage?: AuthStorage;
  browserEnv?: BrowserEnv;
  /** Transport-failure retry policy (AC-10356). `{ maxAttempts: 1 }` turns it off. */
  retry?: RetryPolicy;
}

/**
 * Public entry point — wires config (§13) and all four services, mirroring the
 * Unity `EnjoylixSdk` facade. Events (§10) are aggregated here. `purchase`/`age`
 * call `ensureValidToken` first (parity with C#).
 */
export class EnjoylixSdk {
  // ── Public events (§10) ───────────────────────────────────────────────────
  readonly onPopupBlocked = new Signal<[string]>();
  readonly onLoginCompleted = new Signal<[LoginKind, boolean]>();
  readonly onTokenReceived = new Signal<[string]>();
  readonly onAuthError = new Signal<[Error]>();
  readonly onValidationError = new Signal<[ValidationErrorResponse]>();

  readonly config: ResolvedConfig;

  private readonly auth: AuthService;
  private readonly purchase: PurchaseService;
  private readonly ageVerification: AgeVerificationService;
  private readonly attribution: AttributionService;

  constructor(config: EnjoylixConfig, deps: EnjoylixSdkDeps = {}) {
    this.config = resolveConfig(config);

    const sessionQueryParams = SessionQueryParams.fromQueryString(
      typeof location !== 'undefined' ? location.search : '',
    );
    const urlBuilder = new UrlBuilder(this.config, sessionQueryParams);
    const http = new RetryingHttpClient(deps.httpClient ?? new FetchHttpClient(), deps.retry);
    const storage = deps.storage ?? new LocalStorageAuthStorage();
    const env = deps.browserEnv ?? new WindowBrowserEnv();

    this.auth = new AuthService({
      urlBuilder,
      api: new AuthApiClient(http, urlBuilder),
      storage,
      transport: new BrowserAuthLoginTransport(env, this.config.portalOrigins),
      authMode: this.config.authMode,
      projectName: this.config.projectName,
      isInsideIframe: () => env.isInsideIframe(),
    });

    this.purchase = new PurchaseService({
      api: new PurchaseApiClient(http, urlBuilder, this.config.signSecret),
      urlBuilder,
      env,
      portalOrigins: this.config.portalOrigins,
    });

    this.ageVerification = new AgeVerificationService({
      api: new AgeVerificationApiClient(http, urlBuilder),
      urlBuilder,
      env,
      portalOrigins: this.config.portalOrigins,
    });

    const attributionContext: AttributionContext = { platformId: this.config.platform };
    if (this.config.additionalAttributionContext['partner']) {
      attributionContext.queryParams = this.config.additionalAttributionContext;
    }
    this.attribution = new AttributionService({
      http,
      urlBuilder,
      platform: this.config.platform,
      authIdProvider: () => this.auth.enjoylixId ?? this.auth.guestId,
      context: attributionContext,
      sessionQueryParams,
    });

    this.wireEvents();
  }

  private wireEvents(): void {
    this.auth.onPopupBlocked.add((url) => this.onPopupBlocked.emit(url));
    this.purchase.onPopupBlocked.add((url) => this.onPopupBlocked.emit(url));
    this.ageVerification.onPopupBlocked.add((url) => this.onPopupBlocked.emit(url));
    this.auth.onLoginCompleted.add((kind, ok) => this.onLoginCompleted.emit(kind, ok));
    this.auth.onTokenReceived.add((t) => this.onTokenReceived.emit(t));
    this.auth.onAuthError.add((e) => this.onAuthError.emit(e));
    this.auth.onValidationError.add((v) => this.onValidationError.emit(v));
    this.auth.onSessionApplied.add(() => this.handleSessionApplied());
  }

  private handleSessionApplied(): void {
    this.attribution.startSessionPing();
  }

  // ── Auth state (§0) ───────────────────────────────────────────────────────
  get isEmailLogin(): boolean {
    return this.auth.isEmailLogin;
  }
  get isKnownFullAccount(): boolean {
    return this.auth.isKnownFullAccount;
  }
  get enjoylixId(): string | null {
    return this.auth.enjoylixId;
  }
  get accessToken(): string | null {
    return this.auth.accessToken;
  }

  // ── Auth API (§5) ─────────────────────────────────────────────────────────
  initialize(): void {
    this.auth.initialize();
  }
  logout(): void {
    this.auth.logout();
    this.attribution.clearAuthId();
    this.attribution.stopSessionPing();
  }
  ensureValidToken(): Promise<AuthSession> {
    return this.auth.ensureValidToken();
  }
  loginGuest(deviceId: string): Promise<string> {
    return this.auth.loginGuest(deviceId);
  }
  loginOpenId(timeoutMs: number = LOGIN_TIMEOUT_MS): Promise<AuthSession | null> {
    return this.auth.loginOpenId(timeoutMs);
  }
  /** Login-on-start; picks popup vs iframe by `authMode` (default 'auto'). */
  loginOnStart(
    timeoutMs: number = ON_START_TIMEOUT_MS,
    deviceId?: string,
  ): Promise<AuthSession | null> {
    return this.auth.loginOnStart(timeoutMs, deviceId);
  }
  linkGuest(deviceId: string, timeoutMs: number = LOGIN_TIMEOUT_MS): Promise<AuthSession | null> {
    return this.auth.linkGuest(deviceId, timeoutMs);
  }
  performLoginWithToken(token: string): Promise<AuthSession> {
    return this.auth.tokenLogin(token);
  }
  /**
   * Mints a one-time `auth_ticket` for the game backend, which validates it against
   * Enjoylix to learn who the player is. Expires in ~60s and is burned on first
   * validation — request one per call, never cache it.
   */
  createGameSessionTicket(): Promise<string | null> {
    return this.auth.createGameSessionTicket();
  }

  // ── Purchase API (§6) ─────────────────────────────────────────────────────
  async purchaseCreate(
    req: PurchaseCreateRequest,
    timeoutMs: number = PURCHASE_TIMEOUT_MS,
  ): Promise<PaymentResult | null> {
    const session = await this.auth.ensureValidToken();
    return this.purchase.createOpenAndWait(session.accessToken, req, timeoutMs);
  }

  // ── Age verification API (§7) ─────────────────────────────────────────────
  async isAgeVerificationNeeded(): Promise<boolean> {
    const session = await this.auth.ensureValidToken();
    return this.ageVerification.isVerificationNeeded(session.accessToken);
  }
  async startAgeVerification(timeoutMs: number = AGE_TIMEOUT_MS): Promise<boolean> {
    const session = await this.auth.ensureValidToken();
    return this.ageVerification.startVerification(session.accessToken, timeoutMs);
  }

  // ── Attribution API (§8, fire-and-forget) ─────────────────────────────────
  /** Hands over the in-game profile id. Releases the session ping (§8, ATTR-06). */
  setPlayerId(playerId: string): void {
    this.attribution.updateContext({ playerId });
  }
  trackLogin(): void {
    void this.attribution.trackLogin();
  }
  trackRegistration(): void {
    void this.attribution.trackRegistration();
  }
  trackTutorialComplete(): void {
    void this.attribution.trackTutorialComplete();
  }
  trackPurchase(params: {
    eventType: string;
    source: string;
    checkoutId: string;
    transactionId: string;
    amount: number;
    currencyCode: string;
    isQaPurchase: boolean;
  }): void {
    void this.attribution.trackPurchase(params);
  }
  updateAttributionContext(ctx: AttributionContext): void {
    this.attribution.updateContext(ctx);
  }
}
