import type { AuthMode } from '../config/types.js';
import type { LoginKind } from '../config/types.js';
import type { UrlBuilder } from '../net/UrlBuilder.js';
import {
  EnjoylixApiError,
  PopupBlockedError,
  isNetworkError,
  type ValidationErrorResponse,
} from '../net/errors.js';
import { generatePkcePair, type PkcePair } from '../net/pkce.js';
import type { AuthStorage } from '../storage/AuthStorage.js';
import { Signal } from '../common/Signal.js';
import type { AuthApi } from './AuthApiClient.js';
import type { AuthLoginTransport } from './AuthLoginTransport.js';
import type { AuthSession, OpenIdUserResponse } from './models.js';

const DEFAULT_FLOW_TIMEOUT_MS = 120_000;

/**
 * How long a `/me` answer stays reusable for the same access token (AC-9516). Long enough
 * to collapse the burst a single flow makes, short enough that `ensureValidToken` keeps
 * working as a token probe.
 */
const DEFAULT_ME_CACHE_TTL_MS = 15_000;

export interface AuthServiceDeps {
  urlBuilder: UrlBuilder;
  api: AuthApi;
  storage: AuthStorage;
  transport: AuthLoginTransport;
  authMode: AuthMode;
  /** `game_name` of a game session ticket — the `projectName` from the config. */
  projectName: string;
  /** `window.parent !== window` — drives 'auto' login-on-start (TRANS-02). */
  isInsideIframe: () => boolean;
  /** Override PKCE generation (deterministic tests). */
  pkce?: () => Promise<PkcePair>;
  defaultFlowTimeoutMs?: number;
  /** Reuse window for `/me` per access token (AC-9516). `0` disables the cache. */
  meCacheTtlMs?: number;
  /** Injected clock (deterministic tests). */
  now?: () => number;
}

function isHttpStatus(e: unknown, code: number): boolean {
  return e instanceof EnjoylixApiError && e.statusCode === code;
}

function toError(e: unknown): Error {
  return e instanceof Error ? e : new Error(String(e));
}

/**
 * Auth state machine (contract §5). Port of C# `AuthService`, with the documented
 * JS fixes: refresh treats **401 AND 403** as "refresh invalid → relogin" (§1.1,
 * AUTH-REFRESH-02), and clearing the session actually removes the stored access token.
 */
export class AuthService {
  // ── Public events (contract §10) ──────────────────────────────────────────
  readonly onTokenReceived = new Signal<[string]>();
  readonly onSessionApplied = new Signal<[]>();
  readonly onAuthError = new Signal<[Error]>();
  readonly onPopupBlocked = new Signal<[string]>();
  readonly onLoginCompleted = new Signal<[LoginKind, boolean]>();
  readonly onValidationError = new Signal<[ValidationErrorResponse]>();

  // ── In-memory state (contract §0) ─────────────────────────────────────────
  private _accessToken: string | null = null;
  private _guestId: string | null = null;
  private _deviceId: string | null = null;
  private _me: OpenIdUserResponse | null = null;

  private readonly urlBuilder: UrlBuilder;
  private readonly api: AuthApi;
  private readonly storage: AuthStorage;
  private readonly transport: AuthLoginTransport;
  private readonly authMode: AuthMode;
  private readonly gameName: string;
  private readonly isInsideIframe: () => boolean;
  private readonly pkce: () => Promise<PkcePair>;
  private readonly defaultTimeout: number;
  private readonly meCacheTtl: number;
  private readonly now: () => number;

  /** Serializes EnsureValidToken (purchase + UI etc.) — C# `SemaphoreSlim(1,1)`. */
  private gate: Promise<unknown> = Promise.resolve();

  private meCache: { token: string; me: OpenIdUserResponse; at: number } | null = null;
  private meInFlight: { token: string; promise: Promise<OpenIdUserResponse> } | null = null;

  constructor(deps: AuthServiceDeps) {
    this.urlBuilder = deps.urlBuilder;
    this.api = deps.api;
    this.storage = deps.storage;
    this.transport = deps.transport;
    this.authMode = deps.authMode;
    this.gameName = deps.projectName;
    this.isInsideIframe = deps.isInsideIframe;
    this.pkce = deps.pkce ?? generatePkcePair;
    this.defaultTimeout = deps.defaultFlowTimeoutMs ?? DEFAULT_FLOW_TIMEOUT_MS;
    this.meCacheTtl = deps.meCacheTtlMs ?? DEFAULT_ME_CACHE_TTL_MS;
    this.now = deps.now ?? Date.now;
  }

  // ── Derived state (contract §0) ───────────────────────────────────────────
  get accessToken(): string | null {
    return this._accessToken;
  }
  get guestId(): string | null {
    return this._guestId;
  }
  get deviceId(): string | null {
    return this._deviceId;
  }
  get me(): OpenIdUserResponse | null {
    return this._me;
  }
  get enjoylixId(): string | null {
    return this._me?.id ?? null;
  }
  get isEmailLogin(): boolean {
    return this._me !== null && !this._me.is_guest;
  }
  /** `storage.is_guest === false` (explicit false, not null). */
  get isKnownFullAccount(): boolean {
    return this.storage.loadIsGuest() === false;
  }

  // ── Lifecycle (§5.1) ──────────────────────────────────────────────────────

  /** Loads saved ids/token into memory. No network, no auto-login (AUTH-INIT-01/02). */
  initialize(): void {
    this._deviceId = this.storage.loadDeviceId();
    this._guestId = this.storage.loadGuestId();
    const savedToken = this.storage.loadAccessToken();
    if (savedToken) this._accessToken = savedToken;
  }

  /** Clears in-memory state and storage (keeps device_id) (AUTH-LOGOUT-01). */
  logout(): void {
    this._guestId = null;
    this._accessToken = null;
    this._me = null;
    this.invalidateMeCache();
    this.storage.clear();
  }

  // ── EnsureValidToken (§5.2) ───────────────────────────────────────────────

  /** Call before any token-using request. Re-auths if the token is missing/expired. */
  ensureValidToken(): Promise<AuthSession> {
    return this.runExclusive(async () => {
      try {
        if (!this._accessToken) return await this.tryRefreshOrRelogin();
        try {
          const me = await this.fetchMe(this._accessToken);
          this.applySession(this._accessToken, me);
          return { accessToken: this._accessToken, me };
        } catch (e) {
          if (isHttpStatus(e, 401)) return await this.tryRefreshOrRelogin();
          throw e; // 500/network etc. — do NOT relogin (AUTH-ENSURE-04)
        }
      } catch (e) {
        this.emitValidationIfAny(e);
        this.onAuthError.emit(toError(e));
        throw e;
      }
    });
  }

  // ── Guest login (§5.4) ────────────────────────────────────────────────────

  async loginGuest(deviceId: string): Promise<string> {
    try {
      if (!deviceId) throw new Error('deviceId is empty');

      this._deviceId = deviceId;
      this.storage.saveDeviceId(deviceId);

      const resp = await this.api.guestLogin(deviceId);

      this._guestId = resp.id || null;
      if (this._guestId) this.storage.saveGuestId(this._guestId);
      if (resp.refresh_token) this.storage.saveRefreshToken(resp.refresh_token);

      await this.processAccessToken(resp.access_token);

      this.onLoginCompleted.emit('GuestLogin', !!this._guestId);
      return this._guestId ?? '';
    } catch (e) {
      if (isHttpStatus(e, 409)) {
        // Device is linked to a full account — persist so relogin won't retry guest.
        this.storage.saveIsGuest(false);
        this.clearStoredTokens();
      }
      this.emitValidationIfAny(e);
      this.onAuthError.emit(toError(e));
      this.onLoginCompleted.emit('GuestLogin', false);
      throw e;
    }
  }

  // ── OpenID login (§5.5) ───────────────────────────────────────────────────

  /** Popup login. Returns `null` (not throw) when the popup is blocked (AUTH-OID-02). */
  async loginOpenId(timeoutMs: number = this.defaultTimeout): Promise<AuthSession | null> {
    try {
      const { codeVerifier, codeChallenge } = await this.pkce();
      const url = this.urlBuilder.buildAuthPageUrl({ isLink: false, codeChallenge });
      const authCode = await this.transport.popupLogin(url, timeoutMs);
      const session = await this.processAuthCode(authCode, codeVerifier);
      this.onLoginCompleted.emit('OpenIdLogin', true);
      return session;
    } catch (e) {
      if (e instanceof PopupBlockedError) {
        this.onPopupBlocked.emit(e.url);
        this.onLoginCompleted.emit('OpenIdLogin', false);
        return null;
      }
      this.emitValidationIfAny(e);
      this.onAuthError.emit(toError(e));
      this.onLoginCompleted.emit('OpenIdLogin', false);
      throw e;
    }
  }

  /** Iframe-portal login-on-start (AUTH-OID-05). No popup → no popup-blocked path. */
  async loginOnStartWeb(timeoutMs: number = this.defaultTimeout): Promise<AuthSession> {
    try {
      const { codeVerifier, codeChallenge } = await this.pkce();
      const authCode = await this.transport.iframeLogin(codeChallenge, timeoutMs);
      const session = await this.processAuthCode(authCode, codeVerifier);
      this.onLoginCompleted.emit('OpenIdLogin', true);
      return session;
    } catch (e) {
      this.emitValidationIfAny(e);
      this.onAuthError.emit(toError(e));
      this.onLoginCompleted.emit('OpenIdLogin', false);
      throw e;
    }
  }

  /**
   * Standalone login-on-start that reuses the account already tied to the device
   * (AC-10433). Restores a stored session without any popup first; only if that
   * fails does it open the portal, passing `device_id` + `insta_reg` so the portal
   * returns the existing account instead of minting a second guest.
   */
  async loginOnStartNative(
    deviceId?: string,
    timeoutMs: number = this.defaultTimeout,
  ): Promise<AuthSession | null> {
    if (deviceId) {
      this._deviceId = deviceId;
      this.storage.saveDeviceId(deviceId);
    }
    if (!this._deviceId) this._deviceId = this.storage.loadDeviceId();

    let restored: AuthSession | null;
    try {
      restored = await this.tryRestoreSession();
    } catch (e) {
      // The network is down, not the session (AC-10356). Opening the portal here is what
      // showed the login window to an already-logged-in player.
      this.onAuthError.emit(toError(e));
      this.onLoginCompleted.emit('StartupLogin', false);
      throw e;
    }
    if (restored) {
      this.onLoginCompleted.emit('StartupLogin', true);
      return restored;
    }

    try {
      const { codeVerifier, codeChallenge } = await this.pkce();
      const url = this.urlBuilder.buildAuthPageUrl({
        isLink: false,
        codeChallenge,
        deviceId: this._deviceId ?? undefined,
        instaReg: true,
      });
      const authCode = await this.transport.popupLogin(url, timeoutMs);
      const session = await this.processAuthCode(authCode, codeVerifier);
      this.onLoginCompleted.emit('StartupLogin', true);
      return session;
    } catch (e) {
      if (e instanceof PopupBlockedError) {
        this.onPopupBlocked.emit(e.url);
        this.onLoginCompleted.emit('StartupLogin', false);
        return null;
      }
      this.emitValidationIfAny(e);
      this.onAuthError.emit(toError(e));
      this.onLoginCompleted.emit('StartupLogin', false);
      throw e;
    }
  }

  /**
   * Silent session restore: current token, then refresh token. Never opens a
   * popup — unlike `ensureValidToken`, which falls through to `reLoginByPolicy`.
   *
   * Rejects instead of answering `null` when the failure was the network (AC-10356):
   * `null` means "no session to restore" and the caller acts on it by opening the login
   * portal, which is the wrong answer for a request that never reached the server.
   */
  private async tryRestoreSession(): Promise<AuthSession | null> {
    if (this._accessToken) {
      try {
        const me = await this.fetchMe(this._accessToken);
        this.applySession(this._accessToken, me);
        return { accessToken: this._accessToken, me };
      } catch (e) {
        if (isNetworkError(e)) throw e;
        // token no longer valid — fall through to the refresh token
      }
    }

    const refreshToken = this.storage.loadRefreshToken();
    if (!refreshToken) return null;

    try {
      const pair = await this.api.refreshToken(refreshToken);
      const me = await this.fetchMe(pair.access_token);
      this.applySession(pair.access_token, me);
      this.storage.saveRefreshToken(pair.refresh_token); // rotation!
      this.onTokenReceived.emit(pair.access_token);
      return { accessToken: pair.access_token, me };
    } catch (e) {
      if (isNetworkError(e)) throw e;
      return null;
    }
  }

  /** Picks popup vs iframe for login-on-start by `authMode` (contract §9, TRANS-01..04). */
  loginOnStart(
    timeoutMs: number = this.defaultTimeout,
    deviceId?: string,
  ): Promise<AuthSession | null> {
    if (this.resolveUseIframe()) return this.loginOnStartWeb(timeoutMs);
    return deviceId || this.storage.loadDeviceId()
      ? this.loginOnStartNative(deviceId, timeoutMs)
      : this.loginOpenId(timeoutMs);
  }

  private resolveUseIframe(): boolean {
    switch (this.authMode) {
      case 'iframe':
        return true;
      case 'standalone':
        return false;
      default:
        return this.isInsideIframe();
    }
  }

  // ── Link guest → full (§5.6) ──────────────────────────────────────────────

  async linkGuest(
    deviceId: string,
    timeoutMs: number = this.defaultTimeout,
  ): Promise<AuthSession | null> {
    if (!deviceId) throw new Error('deviceId is empty'); // AUTH-LINK-04: before any side effect

    this._deviceId = deviceId;
    this.storage.saveDeviceId(deviceId);

    await this.ensureValidToken();
    if (this.isEmailLogin) {
      // Already a full account — skip linking (AUTH-LINK-02).
      this.onLoginCompleted.emit('OpenIdLogin', true);
      return { accessToken: this._accessToken!, me: this._me! };
    }

    try {
      const { codeVerifier, codeChallenge } = await this.pkce();
      const opts: { isLink: boolean; codeChallenge?: string; token?: string } = {
        isLink: true,
        codeChallenge,
      };
      if (this._accessToken) opts.token = this._accessToken;
      const url = this.urlBuilder.buildAuthPageUrl(opts);

      const authCode = await this.transport.popupLogin(url, timeoutMs);
      const session = await this.processAuthCode(authCode, codeVerifier);
      this.onLoginCompleted.emit('GuestLink', true);
      return session;
    } catch (e) {
      if (e instanceof PopupBlockedError) {
        this.onPopupBlocked.emit(e.url);
        this.onLoginCompleted.emit('GuestLink', false);
        return null;
      }
      this.emitValidationIfAny(e);
      this.onAuthError.emit(toError(e));
      this.onLoginCompleted.emit('GuestLink', false);
      throw e;
    }
  }

  // ── Token login (§5.7) ────────────────────────────────────────────────────

  async tokenLogin(token: string): Promise<AuthSession> {
    try {
      const session = await this.processAccessToken(token);
      this.onLoginCompleted.emit('TokenLogin', true);
      return session;
    } catch (e) {
      this.emitValidationIfAny(e);
      this.onAuthError.emit(toError(e));
      this.onLoginCompleted.emit('TokenLogin', false);
      throw e;
    }
  }

  // ── Game session ticket (§5.8) ────────────────────────────────────────────

  /**
   * One-time ticket proving to the game backend that this user is authenticated here.
   * The server expires it after ~60s and burns it on first validation, so request it
   * immediately before the call that consumes it — never cache or reuse the value.
   * If the backend rejects a ticket, call this again to mint a fresh one.
   */
  async createGameSessionTicket(): Promise<string | null> {
    const session = await this.ensureValidToken();

    try {
      const created = await this.api.createGameSession(session.accessToken, this.gameName);
      return created?.session_token ?? null;
    } catch (e) {
      this.emitValidationIfAny(e);
      this.onAuthError.emit(toError(e));
      throw e;
    }
  }

  // ── Internals ─────────────────────────────────────────────────────────────

  /**
   * `/me` for one access token, at most once per {@link DEFAULT_ME_CACHE_TTL_MS} window
   * and never twice in parallel (AC-9516). Linking used to spend three round-trips on the
   * same profile: the pre-flight `ensureValidToken`, the one behind the freshly minted
   * token, and the game's own call right after.
   */
  private fetchMe(accessToken: string): Promise<OpenIdUserResponse> {
    const cached = this.meCache;
    if (cached && cached.token === accessToken && this.now() - cached.at < this.meCacheTtl) {
      return Promise.resolve(cached.me);
    }
    if (this.meInFlight?.token === accessToken) return this.meInFlight.promise;

    const promise = this.api.getMe(accessToken).then(
      (me) => {
        this.meCache = { token: accessToken, me, at: this.now() };
        if (this.meInFlight?.token === accessToken) this.meInFlight = null;
        return me;
      },
      (e: unknown) => {
        if (this.meCache?.token === accessToken) this.meCache = null;
        if (this.meInFlight?.token === accessToken) this.meInFlight = null;
        throw e;
      },
    );
    this.meInFlight = { token: accessToken, promise };
    return promise;
  }

  private invalidateMeCache(): void {
    this.meCache = null;
    this.meInFlight = null;
  }

  private async processAccessToken(accessToken: string | null | undefined): Promise<AuthSession> {
    if (!accessToken) throw new Error('Empty access token');
    const me = await this.fetchMe(accessToken);
    this.applySession(accessToken, me);
    this.onTokenReceived.emit(accessToken);
    return { accessToken, me };
  }

  private async tryRefreshOrRelogin(): Promise<AuthSession> {
    const refreshToken = this.storage.loadRefreshToken();

    if (refreshToken) {
      try {
        const pair = await this.api.refreshToken(refreshToken);
        const me = await this.fetchMe(pair.access_token);
        this.applySession(pair.access_token, me);
        this.storage.saveRefreshToken(pair.refresh_token); // rotation!
        this.onTokenReceived.emit(pair.access_token);
        return { accessToken: pair.access_token, me };
      } catch (e) {
        // JS FIX: server returns 403 for not-found/reused/invalidated refresh (§1.1).
        if (isHttpStatus(e, 401) || isHttpStatus(e, 403)) {
          this.storage.saveRefreshToken(null);
        } else {
          throw e; // 500 / network — do NOT relogin (AUTH-REFRESH-03)
        }
      }
    }

    return this.reLoginByPolicy();
  }

  private async reLoginByPolicy(): Promise<AuthSession> {
    // In-memory Me is authoritative; fall back to persisted flag on a fresh page load.
    const isGuest = this._me ? this._me.is_guest : this.storage.loadIsGuest();

    if (isGuest === false) {
      this.clearStoredTokens();
      throw new Error('OpenID session expired. User must log in again.');
    }

    if (!this._deviceId) this._deviceId = this.storage.loadDeviceId();
    if (!this._deviceId) {
      throw new Error(
        'Guest re-login required but DeviceId is unknown. Call loginGuest(deviceId) at least once.',
      );
    }

    try {
      await this.loginGuest(this._deviceId);
      return { accessToken: this._accessToken!, me: this._me! };
    } catch (e) {
      if (isHttpStatus(e, 409)) {
        this.storage.saveIsGuest(false);
        this.clearStoredTokens();
      }
      throw e;
    }
  }

  private async processAuthCode(authCode: string, codeVerifier: string): Promise<AuthSession> {
    if (!authCode) throw new Error('Empty auth code (login canceled or failed)');
    if (!codeVerifier) throw new Error('Empty code verifier (login canceled or failed)');
    const pair = await this.api.getTokensPair(authCode, codeVerifier);
    this.storage.saveRefreshToken(pair.refresh_token);
    return this.processAccessToken(pair.access_token);
  }

  private applySession(token: string, me: OpenIdUserResponse): void {
    this._accessToken = token;
    this._me = me;
    this.storage.saveIsGuest(me.is_guest);
    if (token) this.storage.saveAccessToken(token);
    this.onSessionApplied.emit();
  }

  private clearStoredTokens(): void {
    this._accessToken = null;
    this.invalidateMeCache();
    this.storage.saveAccessToken(null);
    this.storage.saveRefreshToken(null);
  }

  private emitValidationIfAny(e: unknown): void {
    if (e instanceof EnjoylixApiError && (e.validationError?.detail?.length ?? 0) > 0) {
      this.onValidationError.emit(e.validationError!);
    }
  }

  private runExclusive<T>(fn: () => Promise<T>): Promise<T> {
    const run = this.gate.then(fn, fn);
    // Tail never rejects, so a failed call doesn't block the queue forever.
    this.gate = run.then(
      () => undefined,
      () => undefined,
    );
    return run;
  }
}
