import type { HttpClient } from '../net/HttpClient.js';
import { parseJson } from '../net/HttpClient.js';
import type { UrlBuilder } from '../net/UrlBuilder.js';
import type {
  GameSessionResponse,
  GuestLoginResponse,
  OpenIdUserResponse,
  TokensPair,
} from './models.js';

/** REST surface used by {@link AuthService} (interface allows mocking in tests). */
export interface AuthApi {
  guestLogin(deviceId: string): Promise<GuestLoginResponse>;
  getMe(accessToken: string): Promise<OpenIdUserResponse>;
  getTokensPair(authCode: string, codeVerify: string): Promise<TokensPair>;
  refreshToken(refreshToken: string): Promise<TokensPair>;
  createGameSession(accessToken: string, gameName: string): Promise<GameSessionResponse>;
}

/** Default {@link AuthApi} over {@link HttpClient} + {@link UrlBuilder}. Mirrors C# `AuthApiClient`. */
export class AuthApiClient implements AuthApi {
  constructor(
    private readonly http: HttpClient,
    private readonly urls: UrlBuilder,
  ) {}

  async guestLogin(deviceId: string): Promise<GuestLoginResponse> {
    const res = await this.http.send({
      method: 'GET',
      url: this.urls.buildGuestLoginUrl(deviceId),
      context: 'AuthApiClient.GuestLogin',
    });
    return parseJson<GuestLoginResponse>(res);
  }

  async getMe(accessToken: string): Promise<OpenIdUserResponse> {
    const res = await this.http.send({
      method: 'GET',
      url: this.urls.buildUserInfoUrl(),
      context: 'AuthApiClient.GetMe',
      bearer: accessToken,
    });
    return parseJson<OpenIdUserResponse>(res);
  }

  async getTokensPair(authCode: string, codeVerify: string): Promise<TokensPair> {
    const res = await this.http.send({
      method: 'POST',
      url: this.urls.buildTokensPairUrl(),
      context: 'AuthApiClient.GetTokensPair',
      json: { auth_code: authCode, code_verify: codeVerify },
    });
    return parseJson<TokensPair>(res);
  }

  async refreshToken(refreshToken: string): Promise<TokensPair> {
    const res = await this.http.send({
      method: 'POST',
      url: this.urls.buildRefreshTokenUrl(),
      context: 'AuthApiClient.RefreshToken',
      json: { refresh_token: refreshToken },
    });
    return parseJson<TokensPair>(res);
  }

  async createGameSession(accessToken: string, gameName: string): Promise<GameSessionResponse> {
    const res = await this.http.send({
      method: 'POST',
      url: this.urls.buildGameSessionUrl(),
      context: 'AuthApiClient.CreateGameSession',
      bearer: accessToken,
      json: { game_name: gameName },
    });
    return parseJson<GameSessionResponse>(res);
  }
}
