import type { BrowserEnv } from '../transport/BrowserEnv.js';
import { WindowNames, parseAuthResult } from '../transport/messages.js';
import { runPopupFlow, runIframeLoginFlow } from '../transport/flows.js';

/**
 * Returns an `auth_code` for an OpenID login. Abstracts the DOM transport from
 * {@link AuthService} (the state machine) — mirrors C# `WebBrowserService`/`AuthFlow`.
 */
export interface AuthLoginTransport {
  /** Popup login (`window.open` → `auth_result`). Used by LoginOpenId / LinkGuest. */
  popupLogin(url: string, timeoutMs: number): Promise<string>;
  /** Iframe login-on-start (post to `window.parent` → `enjoylix_portal_login_result`). */
  iframeLogin(codeChallenge: string, timeoutMs: number): Promise<string>;
}

/** Real {@link AuthLoginTransport} over {@link BrowserEnv}. */
export class BrowserAuthLoginTransport implements AuthLoginTransport {
  constructor(
    private readonly env: BrowserEnv,
    private readonly allowedOrigins: string[],
  ) {}

  async popupLogin(url: string, timeoutMs: number): Promise<string> {
    const result = await runPopupFlow(this.env, {
      url,
      windowName: WindowNames.auth,
      context: 'login',
      parse: parseAuthResult,
      allowedOrigins: this.allowedOrigins,
      timeoutMs,
    });
    return result.authCode;
  }

  iframeLogin(codeChallenge: string, timeoutMs: number): Promise<string> {
    return runIframeLoginFlow(this.env, {
      codeChallenge,
      allowedOrigins: this.allowedOrigins,
      timeoutMs,
    });
  }
}
