import { CALLER_IDENTITY, CALLER_IDENTITY_HEADER } from './callerIdentity.js';
import { EnjoylixApiError, type ValidationErrorResponse } from './errors.js';

export type HttpMethod = 'GET' | 'POST';

export interface HttpRequest {
  method: HttpMethod;
  url: string;
  /** Short label used in error messages, e.g. "guest_login". */
  context: string;
  /** Bearer access token for authenticated endpoints. */
  bearer?: string;
  /** Request body, JSON-serialized. */
  json?: unknown;
  /** Already-serialized body, sent byte for byte. Takes precedence over `json`. */
  body?: string;
  /** Extra headers merged into the request. */
  headers?: Record<string, string>;
  /**
   * Content-Type for the body (default `application/json`). Attribution sends
   * `text/plain` — the server parses the body as JSON regardless of this header.
   */
  contentType?: string;
}

export interface RawResponse {
  status: number;
  text: string;
}

/**
 * Transport port. A conforming implementation resolves on any 2xx and throws
 * {@link EnjoylixApiError} for non-2xx responses and network failures (statusCode 0).
 */
export interface HttpClient {
  send(req: HttpRequest): Promise<RawResponse>;
}

/** Parse a successful JSON response body into `T`. */
export function parseJson<T>(res: RawResponse): T {
  return JSON.parse(res.text) as T;
}

/** Build an {@link EnjoylixApiError} from a non-2xx response (mirrors C# ApiClientHelper). */
function createError(context: string, status: number, body: string): EnjoylixApiError {
  let message = `[${context}] code ${status}.`;
  let validation: ValidationErrorResponse | undefined;

  if (status === 422) {
    try {
      const parsed = JSON.parse(body) as ValidationErrorResponse;
      if (Array.isArray(parsed?.detail)) {
        validation = parsed;
        const details = parsed.detail.map((d) => d.msg).join(', ');
        if (details) message += ` Details: ${details}`;
      }
    } catch {
      message += ` Details: Couldn't deserialize validation response: ${body}`;
    }
  }

  return new EnjoylixApiError(message, status, body, validation);
}

/** Default {@link HttpClient} backed by the global `fetch`. */
export class FetchHttpClient implements HttpClient {
  constructor(private readonly fetchImpl: typeof fetch = globalThis.fetch.bind(globalThis)) {}

  async send(req: HttpRequest): Promise<RawResponse> {
    const headers: Record<string, string> = {
      [CALLER_IDENTITY_HEADER]: CALLER_IDENTITY,
      ...req.headers,
    };
    if (req.bearer) headers['Authorization'] = `Bearer ${req.bearer}`;

    const init: RequestInit = { method: req.method, headers };
    if (req.body !== undefined) {
      headers['Content-Type'] = req.contentType ?? 'application/json';
      init.body = req.body;
    } else if (req.json !== undefined) {
      headers['Content-Type'] = req.contentType ?? 'application/json';
      init.body = JSON.stringify(req.json);
    }

    let response: Response;
    try {
      response = await this.fetchImpl(req.url, init);
    } catch (err) {
      // Network/transport failure — no HTTP status. statusCode 0 keeps it out of
      // the 401/403 refresh-invalid branch (contract §1.1).
      const reason = err instanceof Error ? err.message : String(err);
      throw new EnjoylixApiError(`[${req.context}] network error: ${reason}`, 0, '');
    }

    const text = await response.text();
    if (!response.ok) {
      throw createError(req.context, response.status, text);
    }
    return { status: response.status, text };
  }
}
