import type { BrowserEnv } from '../transport/BrowserEnv.js';
import { WindowNames, parsePaymentResult } from '../transport/messages.js';
import { runPopupFlow } from '../transport/flows.js';
import { PopupBlockedError, UserDismissedError } from '../net/errors.js';
import type { UrlBuilder } from '../net/UrlBuilder.js';
import { Signal } from '../common/Signal.js';
import type { PurchaseApi } from './PurchaseApiClient.js';
import type { PaymentResult, PurchaseCreateRequest, PurchaseStatusResponse } from './models.js';

const DEFAULT_TIMEOUT_MS = 1_800_000; // 30 min (payment link TTL)
const COMPLETED_STATUS = 'completed';

export interface PurchaseServiceDeps {
  api: PurchaseApi;
  urlBuilder: UrlBuilder;
  env: BrowserEnv;
  /** Portal origins accepted for the inbound payment_result message. */
  portalOrigins: string[];
  defaultTimeoutMs?: number;
}

/**
 * Purchase orchestration (contract §6). `create` → decorate URL → open popup →
 * await `payment_result` matching our `transaction_id`. A new purchase supersedes
 * the previous in-flight one (PUR-07). Mirrors C# `PurchaseService`/`PurchaseFlow`.
 */
export class PurchaseService {
  readonly onPopupBlocked = new Signal<[string]>();

  private readonly api: PurchaseApi;
  private readonly urlBuilder: UrlBuilder;
  private readonly env: BrowserEnv;
  private readonly portalOrigins: string[];
  private readonly defaultTimeout: number;

  /** Supersedes the previously active purchase flow (PUR-07). */
  private activeController: AbortController | null = null;

  constructor(deps: PurchaseServiceDeps) {
    this.api = deps.api;
    this.urlBuilder = deps.urlBuilder;
    this.env = deps.env;
    this.portalOrigins = deps.portalOrigins;
    this.defaultTimeout = deps.defaultTimeoutMs ?? DEFAULT_TIMEOUT_MS;
  }

  /**
   * Creates a payment, opens the checkout popup, and resolves once a matching
   * `payment_result` arrives. Returns `null` if the popup was blocked (PUR-04).
   */
  async createOpenAndWait(
    accessToken: string,
    req: PurchaseCreateRequest,
    timeoutMs: number = this.defaultTimeout,
  ): Promise<PaymentResult | null> {
    const created = await this.api.create(accessToken, req);
    const url = this.urlBuilder.decoratePurchaseUrl(created.transaction_url);

    // Supersede any in-flight purchase (PUR-07).
    this.activeController?.abort();
    const controller = new AbortController();
    this.activeController = controller;

    try {
      const result = await runPopupFlow<PaymentResult>(this.env, {
        url,
        windowName: WindowNames.pay,
        context: 'purchase',
        allowedOrigins: this.portalOrigins,
        timeoutMs,
        signal: controller.signal,
        parse: (data) => {
          const payment = parsePaymentResult(data);
          // Ignore results for a different transaction (PUR-02).
          if (!payment || payment.gameTransactionId !== req.transaction_id) return null;
          return {
            success: payment.success,
            paymentId: payment.paymentId,
            transactionId: payment.gameTransactionId,
            raw: data,
          };
        },
      });
      return result;
    } catch (e) {
      if (e instanceof PopupBlockedError) {
        this.onPopupBlocked.emit(e.url);
        return null;
      }
      // Safety net: the popup was closed without a payment_result, but the payment
      // may have succeeded server-side (the postMessage can be lost). Make a single
      // check of the coin-spend status before surfacing the dismiss.
      if (e instanceof UserDismissedError) {
        const reconciled = await this.tryReconcile(accessToken, req);
        if (reconciled) return reconciled;
      }
      throw e;
    } finally {
      if (this.activeController === controller) this.activeController = null;
    }
  }

  /**
   * Single safety-net query: resolves to a successful {@link PaymentResult} only if the
   * server reports the coin spend as `completed`; otherwise `null`, so the caller rethrows
   * {@link UserDismissedError}. Any other status, a 404, or a network error means "not completed".
   */
  private async tryReconcile(
    accessToken: string,
    req: PurchaseCreateRequest,
  ): Promise<PaymentResult | null> {
    try {
      const status = await this.api.coinSpendStatus(
        accessToken,
        req.game_name,
        req.transaction_id,
      );
      if (status && status.status?.toLowerCase() === COMPLETED_STATUS) {
        return {
          success: true,
          paymentId: status.id,
          transactionId: req.transaction_id,
          raw: status,
        };
      }
    } catch {
      // 404 (not found / other user), network errors, etc. — treat as not completed.
    }
    return null;
  }

  create(accessToken: string, req: PurchaseCreateRequest): Promise<{ transaction_url: string }> {
    return this.api.create(accessToken, req);
  }

  complete(accessToken: string, paymentId: string): Promise<string> {
    return this.api.complete(accessToken, paymentId);
  }

  status(accessToken: string, paymentId: string): Promise<PurchaseStatusResponse> {
    return this.api.status(accessToken, paymentId);
  }
}
