import type { BrowserEnv, MessageLike } from './BrowserEnv.js';
import { MessageTypes, parsePortalLoginResult } from './messages.js';
import {
  PopupBlockedError,
  UserDismissedError,
  FlowTimeoutError,
  FlowCanceledError,
} from '../net/errors.js';

const DEFAULT_TIMEOUT_MS = 120_000;
const CLOSED_POLL_MS = 500;

export interface PopupFlowOptions<T> {
  url: string;
  windowName: string;
  context: string;
  /** Returns a result, or `null` to keep waiting (e.g. foreign message). */
  parse: (data: unknown) => T | null;
  /** Accepted message origins. Empty array disables origin validation. */
  allowedOrigins: string[];
  timeoutMs?: number;
  windowFeatures?: string;
  /** Aborts the flow (rejects with {@link FlowCanceledError}) — e.g. a newer purchase. */
  signal?: AbortSignal;
}

function originAllowed(origin: string, allowed: string[]): boolean {
  return allowed.length === 0 || allowed.includes(origin);
}

/**
 * Opens a popup and resolves with the first matching `message` (filtered by
 * `event.source === popup` and origin). Throws {@link PopupBlockedError} if the
 * popup is blocked, {@link UserDismissedError} if closed early, {@link FlowTimeoutError}
 * on timeout. Used by LoginOpenId, Purchase, Age — all popup (contract §2.A, §9).
 */
export function runPopupFlow<T>(env: BrowserEnv, opts: PopupFlowOptions<T>): Promise<T> {
  if (opts.signal?.aborted) {
    return Promise.reject(new FlowCanceledError());
  }
  const handle = env.open(opts.url, opts.windowName, opts.windowFeatures);
  if (!handle) {
    return Promise.reject(new PopupBlockedError(opts.url));
  }

  return new Promise<T>((resolve, reject) => {
    let settled = false;
    let unsubscribe = (): void => {};
    let pollTimer: ReturnType<typeof setInterval>;
    let timeoutTimer: ReturnType<typeof setTimeout>;
    let onAbort = (): void => {};

    const cleanup = (closePopup: boolean): void => {
      settled = true;
      unsubscribe();
      clearInterval(pollTimer);
      clearTimeout(timeoutTimer);
      opts.signal?.removeEventListener('abort', onAbort);
      if (closePopup && !handle.closed) handle.close();
    };

    const onMessage = (e: MessageLike): void => {
      if (settled) return;
      if (e.source !== handle.source) return;
      if (!originAllowed(e.origin, opts.allowedOrigins)) return;
      const result = opts.parse(e.data);
      if (result === null) return;
      cleanup(true);
      resolve(result);
    };

    unsubscribe = env.onMessage(onMessage);

    pollTimer = setInterval(() => {
      if (settled) return;
      if (handle.closed) {
        cleanup(false);
        reject(new UserDismissedError());
      }
    }, CLOSED_POLL_MS);

    timeoutTimer = setTimeout(() => {
      if (settled) return;
      cleanup(true);
      reject(new FlowTimeoutError(opts.context));
    }, opts.timeoutMs ?? DEFAULT_TIMEOUT_MS);

    if (opts.signal) {
      onAbort = (): void => {
        if (settled) return;
        cleanup(true);
        reject(new FlowCanceledError());
      };
      opts.signal.addEventListener('abort', onAbort, { once: true });
    }
  });
}

export interface IframeLoginOptions {
  codeChallenge: string;
  /** Portal origins accepted for the inbound result (TRANS-07). */
  allowedOrigins: string[];
  timeoutMs?: number;
}

/**
 * Login-on-start via the iframe portal: posts `enjoylix_portal_login_request` to
 * `window.parent` and awaits `enjoylix_portal_login_result`. Rejects on the portal's
 * `{ error }` field without waiting for timeout (TRANS-06). Contract §2.B, §9.
 */
export function runIframeLoginFlow(
  env: BrowserEnv,
  opts: IframeLoginOptions,
): Promise<string> {
  return new Promise<string>((resolve, reject) => {
    let settled = false;
    let unsubscribe = (): void => {};
    let timeoutTimer: ReturnType<typeof setTimeout>;

    const cleanup = (): void => {
      settled = true;
      unsubscribe();
      clearTimeout(timeoutTimer);
    };

    const onMessage = (e: MessageLike): void => {
      if (settled) return;
      // Source must be the parent window, origin must be a known portal (TRANS-07).
      if (e.source !== env.parentSource()) return;
      if (!originAllowed(e.origin, opts.allowedOrigins)) return;
      const result = parsePortalLoginResult(e.data);
      if (result === null) return;
      cleanup();
      if (result.error) {
        reject(new Error(`Portal login failed: ${result.error}`));
      } else {
        resolve(result.authCode!);
      }
    };

    unsubscribe = env.onMessage(onMessage);

    // §12 p1: request is posted with "*"; the inbound result is origin-validated above.
    env.postToParent(
      { type: MessageTypes.portalLoginRequest, code_challenge: opts.codeChallenge },
      '*',
    );

    timeoutTimer = setTimeout(() => {
      if (settled) return;
      cleanup();
      reject(new FlowTimeoutError('iframe_login'));
    }, opts.timeoutMs ?? DEFAULT_TIMEOUT_MS);
  });
}
