import type { SessionQueryParams } from '../common/SessionQueryParams.js';
import type { ResolvedConfig } from '../config/types.js';

/** REST paths and portal pages. Mirrors C# `Endpoints`. */
export const Endpoints = {
  loginPage: '/login',
  linkGuestPage: '/link-guest',
  ageVerificationPage: '/age-verification',
  guestLogin: '/api/v2/auth/{project}/guest_login',
  userInfo: '/api/v1/users/me',
  tokensPair: '/api/v2/auth/{project}/token',
  refreshToken: '/api/v2/auth/refresh',
  gameSession: '/api/v2/auth/game_session',
  checkVerificationNeeded: '/api/v1/age_verification/{project}/check_needed',
  purchaseCreate: '/api/v1/purchase/create',
  purchaseComplete: '/api/v1/purchase/complete',
  purchaseStatus: '/api/v1/purchase/status',
  coinSpendStatus: '/api/v1/purchase/coin_spend_status',
  attributionEvent: '/ingame/{project}/event',
} as const;

type Query = Record<string, string | undefined>;

function construct(host: string, path: string, query?: Query): string {
  let url = host.replace(/\/+$/, '');
  url += path.startsWith('/') ? path : `/${path}`;

  if (query) {
    const params = new URLSearchParams();
    for (const [key, value] of Object.entries(query)) {
      if (value !== undefined && value !== '') params.append(key, value);
    }
    const qs = params.toString();
    if (qs) url += `?${qs}`;
  }
  return url;
}

/**
 * Builds every REST and portal URL the SDK needs. Web-only: `return_type` is always
 * `post_message` (deeplink branches are dropped — contract §11). Mirrors C# `UrlBuilder`.
 */
export class UrlBuilder {
  constructor(
    private readonly config: ResolvedConfig,
    private readonly sessionQueryParams?: SessionQueryParams,
  ) {}

  private get base(): string {
    return this.config.baseUrl;
  }

  private project(path: string): string {
    return path.replace('{project}', this.config.projectName);
  }

  private get extra(): Query {
    return this.config.additionalAttributionContext;
  }

  buildGuestLoginUrl(deviceId: string): string {
    return construct(this.base, this.project(Endpoints.guestLogin), {
      device_id: deviceId,
      platform: this.config.platform,
      ...this.extra,
    });
  }

  /** Portal login / link-guest page. `isLink` selects `/link-guest`. */
  buildAuthPageUrl(opts: {
    isLink: boolean;
    codeChallenge?: string;
    token?: string;
    /** Lets the portal reuse the account already tied to this device (AC-10433). */
    deviceId?: string | undefined;
    /** Portal returns straight to the game, creating a guest only if there is none (AC-10433). */
    instaReg?: boolean;
  }): string {
    const path = opts.isLink ? Endpoints.linkGuestPage : Endpoints.loginPage;
    return construct(this.base, path, {
      project_name: this.config.projectName,
      lang: this.config.lang,
      platform: this.config.platform,
      token: opts.token,
      return_type: 'post_message',
      code_challenge: opts.codeChallenge,
      device_id: opts.deviceId,
      insta_reg: opts.instaReg ? 'true' : undefined,
      ...this.extra,
    });
  }

  buildUserInfoUrl(): string {
    return construct(this.base, Endpoints.userInfo);
  }

  /** Carries the launch query params so the backend can attribute the in-game registration. */
  buildTokensPairUrl(): string {
    return construct(this.base, this.project(Endpoints.tokensPair), this.sessionQueryParams?.values);
  }

  buildRefreshTokenUrl(): string {
    return construct(this.base, Endpoints.refreshToken);
  }

  buildGameSessionUrl(): string {
    return construct(this.base, Endpoints.gameSession);
  }

  buildCheckVerificationNeededUrl(): string {
    return construct(this.base, this.project(Endpoints.checkVerificationNeeded), {
      platform: this.config.platform,
    });
  }

  buildAgeVerificationPageUrl(accessToken?: string): string {
    return construct(this.base, Endpoints.ageVerificationPage, {
      project_name: this.config.projectName,
      access_token: accessToken,
      return_type: 'post_message',
    });
  }

  buildPurchaseCreateUrl(): string {
    return construct(this.base, Endpoints.purchaseCreate);
  }

  buildPurchaseCompleteUrl(): string {
    return construct(this.base, Endpoints.purchaseComplete);
  }

  buildPurchaseStatusUrl(paymentId: string): string {
    return construct(this.base, Endpoints.purchaseStatus, { payment_id: paymentId });
  }

  buildCoinSpendStatusUrl(gameName: string, gameTransactionId: string): string {
    return construct(this.base, Endpoints.coinSpendStatus, {
      game_name: gameName,
      game_transaction_id: gameTransactionId,
    });
  }

  buildAttributionUrl(): string {
    return this.config.attributionUrl + this.project(Endpoints.attributionEvent);
  }

  /**
   * Appends `project_name`, `lang`, `return_type=post_message` to the server-issued
   * `transaction_url` (which already carries token/payment_id/etc.). Contract §6.
   */
  decoratePurchaseUrl(transactionUrl: string): string {
    const sep = transactionUrl.includes('?') ? '&' : '?';
    const params = new URLSearchParams({
      project_name: this.config.projectName,
      lang: this.config.lang,
      return_type: 'post_message',
    });
    return `${transactionUrl}${sep}${params.toString()}`;
  }
}
