/** Validation error body returned by the server on HTTP 422 (FastAPI shape). */
export interface ValidationErrorDetail {
  loc: (string | number)[];
  msg: string;
  type: string;
}

export interface ValidationErrorResponse {
  detail: ValidationErrorDetail[];
}

/**
 * Thrown for any non-2xx REST response (and network failures, with `statusCode === 0`).
 * Mirrors C# `EnjoylixApiException`. Contract §1.1.
 */
export class EnjoylixApiError extends Error {
  readonly statusCode: number;
  readonly responseBody: string;
  readonly validationError?: ValidationErrorResponse;

  constructor(
    message: string,
    statusCode: number,
    responseBody: string,
    validationError?: ValidationErrorResponse,
  ) {
    super(message);
    this.name = 'EnjoylixApiError';
    this.statusCode = statusCode;
    this.responseBody = responseBody;
    if (validationError) this.validationError = validationError;
    // Restore prototype chain for instanceof across transpile targets.
    Object.setPrototypeOf(this, EnjoylixApiError.prototype);
  }
}

/** `statusCode` used for transport failures that never produced an HTTP response. */
export const NETWORK_ERROR_STATUS = 0;

/**
 * True for a transport failure (DNS, offline, CORS, aborted socket) — the request never
 * reached a status line. Such a failure is retryable and must never be read as "the user
 * is logged out" (contract §5.10, AC-10356).
 */
export function isNetworkError(e: unknown): boolean {
  return e instanceof EnjoylixApiError && e.statusCode === NETWORK_ERROR_STATUS;
}

/** Raised when the browser blocks `window.open` for a login/purchase/age popup. */
export class PopupBlockedError extends Error {
  readonly url: string;
  constructor(url: string) {
    super('Popup window was blocked by the browser.');
    this.name = 'PopupBlockedError';
    this.url = url;
    Object.setPrototypeOf(this, PopupBlockedError.prototype);
  }
}

/** Raised when a popup/iframe flow exceeds its timeout without a result. */
export class FlowTimeoutError extends Error {
  constructor(context: string) {
    super(`[${context}] timed out waiting for the flow result.`);
    this.name = 'FlowTimeoutError';
    Object.setPrototypeOf(this, FlowTimeoutError.prototype);
  }
}

/** Raised when the user closes the popup/iframe flow without completing it. */
export class UserDismissedError extends Error {
  constructor() {
    super('User closed the external browser or popup without completing the action.');
    this.name = 'UserDismissedError';
    Object.setPrototypeOf(this, UserDismissedError.prototype);
  }
}

/** Raised when a flow is canceled programmatically (e.g. a newer purchase supersedes it). */
export class FlowCanceledError extends Error {
  constructor(reason = 'Flow was canceled.') {
    super(reason);
    this.name = 'FlowCanceledError';
    Object.setPrototypeOf(this, FlowCanceledError.prototype);
  }
}
