import type { HttpClient } from '../net/HttpClient.js';
import { parseJson } from '../net/HttpClient.js';
import type { UrlBuilder } from '../net/UrlBuilder.js';
import type { BrowserEnv } from '../transport/BrowserEnv.js';
import { WindowNames, parseAgeResult } from '../transport/messages.js';
import { runPopupFlow } from '../transport/flows.js';
import { PopupBlockedError } from '../net/errors.js';
import { Signal } from '../common/Signal.js';

const DEFAULT_TIMEOUT_MS = 300_000; // 5 min

interface CheckVerificationNeededResponse {
  age_verification_needed: boolean;
}

/** REST surface for age verification (interface allows mocking). Contract §1, §7. */
export interface AgeVerificationApi {
  checkNeeded(accessToken: string): Promise<boolean>;
}

export class AgeVerificationApiClient implements AgeVerificationApi {
  constructor(
    private readonly http: HttpClient,
    private readonly urls: UrlBuilder,
  ) {}

  async checkNeeded(accessToken: string): Promise<boolean> {
    const res = await this.http.send({
      method: 'GET',
      url: this.urls.buildCheckVerificationNeededUrl(),
      context: 'AgeVerificationApiClient.CheckNeeded',
      bearer: accessToken,
    });
    return parseJson<CheckVerificationNeededResponse>(res).age_verification_needed;
  }
}

export interface AgeVerificationServiceDeps {
  api: AgeVerificationApi;
  urlBuilder: UrlBuilder;
  env: BrowserEnv;
  portalOrigins: string[];
  defaultTimeoutMs?: number;
}

/**
 * Age verification (contract §7). `isVerificationNeeded` checks the server flag;
 * `startVerification` opens the portal popup and resolves with `success`.
 * Mirrors C# `AgeVerificationService`.
 */
export class AgeVerificationService {
  readonly onPopupBlocked = new Signal<[string]>();

  private readonly api: AgeVerificationApi;
  private readonly urlBuilder: UrlBuilder;
  private readonly env: BrowserEnv;
  private readonly portalOrigins: string[];
  private readonly defaultTimeout: number;

  constructor(deps: AgeVerificationServiceDeps) {
    this.api = deps.api;
    this.urlBuilder = deps.urlBuilder;
    this.env = deps.env;
    this.portalOrigins = deps.portalOrigins;
    this.defaultTimeout = deps.defaultTimeoutMs ?? DEFAULT_TIMEOUT_MS;
  }

  isVerificationNeeded(accessToken: string): Promise<boolean> {
    return this.api.checkNeeded(accessToken);
  }

  /** Opens the age-verification popup; resolves `success`, or `false` if popup blocked (AGE-04). */
  async startVerification(
    accessToken: string,
    timeoutMs: number = this.defaultTimeout,
  ): Promise<boolean> {
    const url = this.urlBuilder.buildAgeVerificationPageUrl(accessToken);
    try {
      const result = await runPopupFlow<{ success: boolean }>(this.env, {
        url,
        windowName: WindowNames.age,
        context: 'age_verification',
        allowedOrigins: this.portalOrigins,
        timeoutMs,
        parse: parseAgeResult,
      });
      return result.success;
    } catch (e) {
      if (e instanceof PopupBlockedError) {
        this.onPopupBlocked.emit(e.url);
        return false;
      }
      throw e;
    }
  }
}
