/**
 * Auth storage (contract §4). Web port of C# `IAuthStorage`/`PlayerPrefsAuthStorage`
 * minus AES — `localStorage` is already origin-scoped. Tri-state `is_guest`
 * (`"1"`/`"0"`/absent→null). `clear()` keeps `device_id`.
 */

export const StorageKeys = {
  guestId: 'enjoylix_guest_id',
  accessToken: 'enjoylix_access_token',
  refreshToken: 'enjoylix_refresh_token',
  deviceId: 'enjoylix_device_id',
  isGuest: 'enjoylix_is_guest',
} as const;

/** Minimal `localStorage`-compatible backend (injectable for tests / SSR). */
export interface KeyValueStore {
  getItem(key: string): string | null;
  setItem(key: string, value: string): void;
  removeItem(key: string): void;
}

export interface AuthStorage {
  loadGuestId(): string | null;
  saveGuestId(guestId: string): void;
  loadAccessToken(): string | null;
  /** Falsy token removes the key (so clearing the session actually clears storage). */
  saveAccessToken(token: string | null): void;
  loadRefreshToken(): string | null;
  saveRefreshToken(token: string | null): void;
  loadDeviceId(): string | null;
  saveDeviceId(deviceId: string): void;
  /** Tri-state: `true`/`false`/`null` (key absent). */
  loadIsGuest(): boolean | null;
  saveIsGuest(isGuest: boolean): void;
  /** Removes guest_id, access_token, refresh_token, is_guest — keeps device_id. */
  clear(): void;
}

export class LocalStorageAuthStorage implements AuthStorage {
  private readonly store: KeyValueStore;

  constructor(store?: KeyValueStore) {
    const resolved = store ?? (typeof localStorage !== 'undefined' ? localStorage : undefined);
    if (!resolved) {
      throw new Error('No storage backend available (localStorage missing); inject a KeyValueStore.');
    }
    this.store = resolved;
  }

  loadGuestId(): string | null {
    return this.store.getItem(StorageKeys.guestId);
  }

  saveGuestId(guestId: string): void {
    if (guestId) this.store.setItem(StorageKeys.guestId, guestId);
  }

  loadAccessToken(): string | null {
    return this.store.getItem(StorageKeys.accessToken);
  }

  saveAccessToken(token: string | null): void {
    if (!token) {
      this.store.removeItem(StorageKeys.accessToken);
    } else {
      this.store.setItem(StorageKeys.accessToken, token);
    }
  }

  loadRefreshToken(): string | null {
    return this.store.getItem(StorageKeys.refreshToken);
  }

  saveRefreshToken(token: string | null): void {
    if (!token) {
      this.store.removeItem(StorageKeys.refreshToken);
    } else {
      this.store.setItem(StorageKeys.refreshToken, token);
    }
  }

  loadDeviceId(): string | null {
    return this.store.getItem(StorageKeys.deviceId);
  }

  saveDeviceId(deviceId: string): void {
    if (deviceId) this.store.setItem(StorageKeys.deviceId, deviceId);
  }

  loadIsGuest(): boolean | null {
    const raw = this.store.getItem(StorageKeys.isGuest);
    if (raw === null) return null;
    return raw === '1';
  }

  saveIsGuest(isGuest: boolean): void {
    this.store.setItem(StorageKeys.isGuest, isGuest ? '1' : '0');
  }

  clear(): void {
    this.store.removeItem(StorageKeys.guestId);
    this.store.removeItem(StorageKeys.accessToken);
    this.store.removeItem(StorageKeys.refreshToken);
    this.store.removeItem(StorageKeys.isGuest);
  }
}

/** In-memory {@link KeyValueStore} (tests, SSR fallback). */
export class MemoryKeyValueStore implements KeyValueStore {
  private map = new Map<string, string>();
  getItem(key: string): string | null {
    return this.map.has(key) ? this.map.get(key)! : null;
  }
  setItem(key: string, value: string): void {
    this.map.set(key, value);
  }
  removeItem(key: string): void {
    this.map.delete(key);
  }
}
