import type { EnjoylixConfig, ResolvedConfig, SupportedLang } from './types.js';

/** Built-in environments (contract §13). REST API + portal + postMessage share one host. */
export const ENVIRONMENTS = {
  dev: {
    baseUrl: 'https://stage1.enjoylix.com',
    attributionUrl: 'https://stage1.enjoylix.com',
    portalOrigins: ['https://stage1.enjoylix.com', 'https://stage1.wisecite.com'],
  },
  prod: {
    baseUrl: 'https://enjoylix.com',
    // prod attribution host unconfirmed by server team; reuse baseUrl until provided.
    attributionUrl: 'https://enjoylix.com',
    portalOrigins: ['https://enjoylix.com', 'https://www.enjoylix.com'],
  },
} as const;

const SUPPORTED_LANGS: readonly SupportedLang[] = ['en', 'ru', 'de', 'es', 'fr', 'it'];

/** Primary subtag of a BCP-47 tag, mapped to the portal's supported set (fallback 'en'). */
export function normalizeLang(raw: string | undefined): SupportedLang {
  if (!raw) return 'en';
  const primary = raw.toLowerCase().split('-')[0] as SupportedLang;
  return SUPPORTED_LANGS.includes(primary) ? primary : 'en';
}

function stripTrailingSlash(url: string): string {
  return url.replace(/\/+$/, '');
}

/** Origin (`scheme://host[:port]`) of a URL, for postMessage validation. */
export function originOf(url: string): string {
  return new URL(url).origin;
}

/**
 * Default portal origins for postMessage validation, taken from the env the baseUrl
 * belongs to: prod serves the portal from both `enjoylix.com` and `www.enjoylix.com`,
 * stage from both `stage1.enjoylix.com` and `stage1.wisecite.com`. A baseUrl outside
 * any known env only trusts its own origin. Contract §13.
 */
function defaultPortalOrigins(baseUrl: string, env: EnjoylixConfig['env']): string[] {
  const origin = originOf(baseUrl);
  const envOrigins: readonly string[] | undefined = env
    ? ENVIRONMENTS[env].portalOrigins
    : undefined;
  if (envOrigins?.includes(origin)) return [...envOrigins];
  if (origin === ENVIRONMENTS.prod.baseUrl) return [...ENVIRONMENTS.prod.portalOrigins];
  return [origin];
}

export function resolveConfig(config: EnjoylixConfig): ResolvedConfig {
  if (!config.projectName) throw new Error('EnjoylixConfig.projectName is required');
  if (!config.platform) throw new Error('EnjoylixConfig.platform is required');

  const envDefaults = config.env ? ENVIRONMENTS[config.env] : undefined;
  const baseUrl = config.baseUrl ?? envDefaults?.baseUrl;
  const attributionUrl = config.attributionUrl ?? envDefaults?.attributionUrl;

  if (!baseUrl) {
    throw new Error('EnjoylixConfig requires either `env` or an explicit `baseUrl`');
  }
  if (!attributionUrl) {
    throw new Error('EnjoylixConfig requires either `env` or an explicit `attributionUrl`');
  }

  const cleanBase = stripTrailingSlash(baseUrl);
  const navLang =
    typeof navigator !== 'undefined' ? navigator.language : undefined;

  return {
    projectName: config.projectName,
    platform: config.platform,
    baseUrl: cleanBase,
    attributionUrl: stripTrailingSlash(attributionUrl),
    authMode: config.authMode ?? 'auto',
    portalOrigins:
      config.portalOrigins && config.portalOrigins.length > 0
        ? config.portalOrigins.map(originOf)
        : defaultPortalOrigins(cleanBase, config.env),
    lang: normalizeLang(config.lang ?? navLang),
    additionalAttributionContext: config.additionalAttributionContext ?? {},
    signSecret: config.signSecret ?? '',
  };
}
