/**
 * postMessage payload parsers. Contract §2. Each returns a typed result, or `null`
 * to mean "not my message, keep waiting". The portal posts plain objects, but the
 * Unity bridge stringified them — so we also accept a JSON string (defensive).
 */

/** Window names used for popups (contract §2.A). */
export const WindowNames = {
  auth: 'enjoylix_auth',
  pay: 'enjoylix_pay',
  age: 'enjoylix_age_verification',
} as const;

/** postMessage `type` discriminators. */
export const MessageTypes = {
  authResult: 'auth_result',
  paymentResult: 'payment_result',
  ageResult: 'age_verification_result',
  portalLoginRequest: 'enjoylix_portal_login_request',
  portalLoginResult: 'enjoylix_portal_login_result',
} as const;

type Dict = Record<string, unknown>;

/** Normalize raw event.data into an object, parsing a JSON string if needed. */
function asObject(data: unknown): Dict | null {
  if (typeof data === 'string') {
    try {
      const parsed = JSON.parse(data);
      return typeof parsed === 'object' && parsed !== null ? (parsed as Dict) : null;
    } catch {
      return null;
    }
  }
  return typeof data === 'object' && data !== null ? (data as Dict) : null;
}

function str(v: unknown): string {
  return typeof v === 'string' ? v : '';
}

/** §2.A Auth (v2/PKCE): `{ type:"auth_result", auth_code }`. */
export function parseAuthResult(data: unknown): { authCode: string } | null {
  const o = asObject(data);
  if (!o || o['type'] !== MessageTypes.authResult) return null;
  const authCode = str(o['auth_code']);
  return authCode ? { authCode } : null;
}

export interface PaymentMessage {
  success: boolean;
  paymentId: string;
  gameTransactionId: string;
}

/** §2.A Payment: `{ type:"payment_result", success, payment_id, game_transaction_id }`. Rejects empty payment_id (PUR-05). */
export function parsePaymentResult(data: unknown): PaymentMessage | null {
  const o = asObject(data);
  if (!o || o['type'] !== MessageTypes.paymentResult) return null;
  const paymentId = str(o['payment_id']);
  if (!paymentId) return null;
  return {
    success: o['success'] === true,
    paymentId,
    gameTransactionId: str(o['game_transaction_id']),
  };
}

/** §2.A Age: `{ type:"age_verification_result", success }`. */
export function parseAgeResult(data: unknown): { success: boolean } | null {
  const o = asObject(data);
  if (!o || o['type'] !== MessageTypes.ageResult) return null;
  return { success: o['success'] === true };
}

/** §2.B iframe result: `{ type:"enjoylix_portal_login_result", auth_code | error }`. */
export function parsePortalLoginResult(
  data: unknown,
): { authCode?: string; error?: string } | null {
  const o = asObject(data);
  if (!o || o['type'] !== MessageTypes.portalLoginResult) return null;
  const authCode = str(o['auth_code']);
  const error = str(o['error']);
  if (authCode) return { authCode };
  if (error) return { error };
  // Result with neither field — malformed; ignore.
  return null;
}
