import { SessionQueryParams } from '../common/SessionQueryParams.js';
import type { HttpClient } from '../net/HttpClient.js';
import type { UrlBuilder } from '../net/UrlBuilder.js';
import { normalizeAuthId, normalizeCurrencyCode } from './contract.js';

/**
 * Mutable attribution context. Web fields replace the Unity deeplink source:
 * `partner`/query params come from `location.search` instead of a deeplink URL.
 * Contract §8.
 */
export interface AttributionContext {
  playerId?: string;
  authId?: string;
  countryCode?: string;
  clientIp?: string;
  platformId?: string;
  /** Overrides the query params parsed from `location.search` (source of `partner`). */
  queryParams?: Record<string, string>;
}

/** Base event envelope (contract §8). */
export interface AttributionEvent {
  timestamp: number;
  player_id: string;
  auth_id: string;
  partner: string;
  platform: string;
  event: string;
  event_data: Record<string, unknown>;
}

export interface AttributionServiceDeps {
  http: HttpClient;
  urlBuilder: UrlBuilder;
  /** Envelope `platform` (the configured GamePlatform string). */
  platform: string;
  /**
   * Resolves the current Enjoylix account id when an event is built. Preferred
   * over `context.authId`, which cannot follow logout (ATTR-06b).
   */
  authIdProvider?: () => string | null | undefined;
  context?: AttributionContext;
  /** Shared with `UrlBuilder` so the token request reports the same set. */
  sessionQueryParams?: SessionQueryParams;
  /** Testing/SSR seams. */
  now?: () => number;
  queryString?: () => string;
  userAgent?: () => string;
  referrer?: () => string;
  pingIntervalMs?: number;
  pingPollIntervalMs?: number;
}

const PING_INTERVAL_MS = 6 * 60 * 60 * 1000;
const PING_POLL_INTERVAL_MS = 30_000;

/**
 * Attribution events (contract §8). Fire-and-forget: every `track*` returns a
 * promise that NEVER rejects (network errors are swallowed, ATTR-05). Mirrors
 * C# `AttributionService`.
 */
export class AttributionService {
  private readonly http: HttpClient;
  private readonly urlBuilder: UrlBuilder;
  private readonly platform: string;
  private readonly authIdProvider: (() => string | null | undefined) | undefined;
  private readonly now: () => number;
  private readonly getUserAgent: () => string;
  private readonly getReferrer: () => string;

  private context: AttributionContext;
  private readonly sessionQueryParams: SessionQueryParams;

  private readonly pingIntervalMs: number;
  private readonly pingPollIntervalMs: number;
  private pingTimer: ReturnType<typeof setInterval> | null = null;
  private pingAccountId: string | null = null;
  private pingDueAt = 0;

  constructor(deps: AttributionServiceDeps) {
    this.http = deps.http;
    this.urlBuilder = deps.urlBuilder;
    this.platform = deps.platform;
    this.authIdProvider = deps.authIdProvider;
    this.now = deps.now ?? Date.now;
    this.getUserAgent =
      deps.userAgent ?? (() => (typeof navigator !== 'undefined' ? navigator.userAgent : ''));
    this.getReferrer =
      deps.referrer ?? (() => (typeof document !== 'undefined' ? document.referrer : ''));

    this.pingIntervalMs = deps.pingIntervalMs ?? PING_INTERVAL_MS;
    this.pingPollIntervalMs = deps.pingPollIntervalMs ?? PING_POLL_INTERVAL_MS;

    this.context = deps.context ?? {};
    const queryString =
      deps.queryString ?? (() => (typeof location !== 'undefined' ? location.search : ''));
    this.sessionQueryParams =
      deps.sessionQueryParams ?? SessionQueryParams.fromQueryString(queryString());
    if (this.context.queryParams) this.sessionQueryParams.set(this.context.queryParams);
  }

  trackLogin(): Promise<void> {
    return this.send('login', this.loginRegistrationData());
  }

  trackRegistration(): Promise<void> {
    return this.send('registration', this.loginRegistrationData());
  }

  trackTutorialComplete(): Promise<void> {
    return this.send('tutorial:complete', { is_completed: true });
  }

  trackPing(): Promise<void> {
    return this.send('ping', {});
  }

  startSessionPing(): void {
    const accountId = this.resolveAuthId();
    if (!accountId || !this.context.playerId) return;

    if (this.pingTimer !== null && this.pingAccountId === accountId) return;

    this.stopSessionPing();

    this.pingAccountId = accountId;
    this.pingDueAt = this.now() + this.pingIntervalMs;
    void this.trackPing();

    this.pingTimer = setInterval(() => {
      if (this.now() < this.pingDueAt) return;
      this.pingDueAt = this.now() + this.pingIntervalMs;
      void this.trackPing();
    }, this.pingPollIntervalMs);
  }

  stopSessionPing(): void {
    if (this.pingTimer !== null) {
      clearInterval(this.pingTimer);
      this.pingTimer = null;
    }
    this.pingAccountId = null;
  }

  trackPurchase(params: {
    eventType: string;
    source: string;
    checkoutId: string;
    transactionId: string;
    amount: number;
    currencyCode: string;
    isQaPurchase: boolean;
  }): Promise<void> {
    return this.send(params.eventType, {
      source: params.source,
      checkout_id: params.checkoutId,
      transaction_id: params.transactionId,
      amount: params.amount,
      currency_code: normalizeCurrencyCode(params.currencyCode),
      is_qa_purchase: params.isQaPurchase,
    });
  }

  /** Merges non-empty fields into the context (mirrors C# `UpdateContext`). */
  updateContext(ctx: AttributionContext): void {
    if (ctx.playerId) this.context.playerId = ctx.playerId;
    if (ctx.authId) this.context.authId = normalizeAuthId(ctx.authId);
    if (ctx.countryCode) this.context.countryCode = ctx.countryCode;
    if (ctx.clientIp) this.context.clientIp = ctx.clientIp;
    if (ctx.platformId) this.context.platformId = ctx.platformId;
    if (ctx.queryParams) this.sessionQueryParams.set(ctx.queryParams);

    this.startSessionPing();
  }

  /** Drops the game-supplied `auth_id` override (mirrors C# `ClearAuthId`). */
  clearAuthId(): void {
    delete this.context.authId;
  }

  /**
   * Resolved when the event is built, not pushed once: a snapshot could not be
   * cleared on logout and was empty until the first session applied.
   */
  private resolveAuthId(): string {
    const fromProvider = normalizeAuthId(this.authIdProvider?.());
    return fromProvider || normalizeAuthId(this.context.authId);
  }

  private loginRegistrationData(): Record<string, unknown> {
    return {
      player_country: this.context.countryCode ?? 'XX',
      platform_id: this.context.platformId ?? this.platform,
      client_ip: this.context.clientIp ?? '127.0.0.1',
      query_params_json: JSON.stringify(this.sessionQueryParams.values),
      user_agent: this.getUserAgent(),
      forwarded_for: '',
      referer: this.getReferrer(),
    };
  }

  private buildEnvelope(event: string, eventData: Record<string, unknown>): AttributionEvent {
    return {
      timestamp: Math.floor(this.now() / 1000),
      player_id: this.context.playerId ?? '',
      auth_id: this.resolveAuthId(),
      partner: this.sessionQueryParams.values['partner'] ?? '',
      platform: this.platform,
      event,
      event_data: eventData,
    };
  }

  private async send(event: string, eventData: Record<string, unknown>): Promise<void> {
    try {
      await this.http.send({
        method: 'POST',
        url: this.urlBuilder.buildAttributionUrl(),
        context: `Attribution.${event}`,
        json: this.buildEnvelope(event, eventData),
        // The server parses the body as JSON whatever this says; text/plain is kept so the
        // request stays valid for CORS setups that only allow simple content types.
        contentType: 'text/plain;charset=UTF-8',
      });
    } catch {
      // Fire-and-forget: attribution failures must never surface to the game (ATTR-05).
    }
  }
}
