/** Baked in at bundle time by tsup (`define`); absent when running from source. */
declare const __ENJOYLIX_SDK_VERSION__: string | undefined;

/** Identifies the calling client and its version on every request (contract §1.2). */
export const CALLER_IDENTITY_HEADER = 'X-Caller-Identity';

/** `source` half of the header value. The Unity package sends `unity-sdk`. */
export const CALLER_SOURCE = 'js-sdk';

/** Fallback version when no real one was baked in. Mirrors C# `SdkVersion.Unknown`. */
export const UNKNOWN_VERSION = 'dev';

/** Mirrors C# `SdkVersion.IsRealVersion`: blank or dot-less falls back to `dev`. */
export function resolveSdkVersion(raw: string | undefined): string {
  const version = raw?.trim();
  return version && version.includes('.') ? version : UNKNOWN_VERSION;
}

/** Version of this SDK build, e.g. `1.0.6`, or `dev` when it cannot be resolved. */
export const SDK_VERSION = resolveSdkVersion(
  typeof __ENJOYLIX_SDK_VERSION__ === 'string' ? __ENJOYLIX_SDK_VERSION__ : undefined,
);

/** Value sent in {@link CALLER_IDENTITY_HEADER}, e.g. `js-sdk/1.0.6`. */
export const CALLER_IDENTITY = `${CALLER_SOURCE}/${SDK_VERSION}`;
